import type { ReactNode } from "react";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";

export function KitChip({ label = "react-ui", dot = "var(--accent)", on = false, onClick, children }: {
  label?: string;
  dot?: string;
  on?: boolean;
  onClick?: () => void;
  children?: ReactNode;
}) {
  return (
    <button type="button" className={"chip tone-neutral size-sm" + (on ? " on" : "")} onClick={onClick}
      style={{ display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer", border: "1px solid " + (on ? "var(--accent)" : "var(--border)"), background: on ? "color-mix(in oklch, var(--accent), transparent 88%)" : "transparent" }}>
      <ColorSwatch color={dot} size={6} />{label}{children}
    </button>
  );
}
